import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gemm_activation_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float gelu(float x) {
    // Approximation or direct formula for GELU
    return 0.5f * x * (1.0f + erff(x / 1.41421356237f)); // 1.41421356237 ~ sqrt(2)
}

__global__ void gemm_activation_kernel(
    const float* x,
    const float* weight,
    const float* bias,
    float* y,
    int B,
    int I,
    int O,
    float scale,
    float min_val,
    float max_val
) {
    // row: batch index
    // col: out_features index
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < B && col < O) {
        float val = 0.0f;
        // GEMM
        for(int i = 0; i < I; i++){
            val += x[row * I + i] * weight[col * I + i];
        }
        // Add bias
        val += bias[col];
        // Scale
        val *= scale;
        // HardTanh
        if (val < min_val) { val = min_val; }
        if (val > max_val) { val = max_val; }
        // GELU
        val = gelu(val);
        // Write result
        y[row * O + col] = val;
    }
}

torch::Tensor gemm_activation_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    float scale,
    float min_val,
    float max_val
) {
    auto B = x.size(0);
    auto I = x.size(1);
    auto O = weight.size(0);

    auto y = torch::empty({B, O}, x.options());

    dim3 block(16, 16);
    dim3 grid((B + block.x - 1) / block.x, (O + block.y - 1) / block.y);

    gemm_activation_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        y.data_ptr<float>(),
        B,
        I,
        O,
        scale,
        min_val,
        max_val
    );

    return y;
}
"""

gemm_activation_cpp_source = r"""
torch::Tensor gemm_activation_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    float scale,
    float min_val,
    float max_val
);
"""

gemm_activation_module = load_inline(
    name="gemm_activation_fused",
    cpp_sources=gemm_activation_cpp_source,
    cuda_sources=gemm_activation_source,
    functions=["gemm_activation_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor, hardtanh_min, hardtanh_max):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))
        self.scaling_factor = scaling_factor
        self.hardtanh_min = hardtanh_min
        self.hardtanh_max = hardtanh_max
        self.gemm_activation = gemm_activation_module

    def forward(self, x):
        return self.gemm_activation.gemm_activation_cuda(
            x,
            self.weight,
            self.bias,
            self.scaling_factor,
            self.hardtanh_min,
            self.hardtanh_max
        )
